from solution import count_integer


def test_issue_example_given():
    """Example: count_integer([1,2,'abc',1.2]) == 2."""
    assert count_integer([1, 2, 'abc', 1.2]) == 2  # 1 + 1 = 2


def test_issue_empty_list():
    """Rule: count integers from a given list."""
    assert count_integer([]) == 0  # empty so 0 = 0


def test_issue_all_integers():
    """Rule: count integers from a given list."""
    assert count_integer([1, 2, 3, 4]) == 4  # 1 + 1 + 1 + 1 = 4


def test_issue_no_integers():
    """Rule: count integers from a given list."""
    assert count_integer(['a', 1.5, None]) == 0  # 0 + 0 + 0 = 0


def test_issue_negative_and_zero():
    """Rule: count integers from a given list."""
    assert count_integer([-1, 0, -5, 3.3]) == 3  # 1 + 1 + 1 + 0 = 3


def test_issue_integer_valued_floats_excluded():
    """Rule: count integers from a given list."""
    assert count_integer([1.0, 2.0, 3]) == 1  # 0 + 0 + 1 = 1


def test_issue_digit_strings_excluded():
    """Rule: count integers from a given list."""
    assert count_integer(['1', '2', 3]) == 1  # 0 + 0 + 1 = 1


def test_issue_nested_list_not_unpacked():
    """Rule: count integers from a given list."""
    assert count_integer([[1, 2], 1]) == 1  # 0 + 1 = 1


def test_issue_large_integers():
    """Rule: count integers from a given list."""
    assert count_integer([10**100, -10**100, 'x']) == 2  # 1 + 1 + 0 = 2


def test_contract_callable():
    """Public interface: solution.count_integer(list1)."""
    assert callable(count_integer)


def test_contract_returns_int():
    """Public interface: solution.count_integer(list1)."""
    assert isinstance(count_integer([1, 'a', 2.5]), int)
